.ct{min-height:100vh;padding:20px;max-width:1500px;margin:auto}.ct-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:18px}.ct-brand{display:flex;align-items:center;gap:12px}.ct-orb{width:44px;height:44px;border-radius:14px;display:grid;place-items:center;background:radial-gradient(circle at 30% 25%,#e9e5ff,#7c5cff 45%,#26184f);box-shadow:0 0 40px rgba(126,91,255,.28)}.ct-head h1{margin:0;font-size:28px}.ct-head p{margin:3px 0 0;color:var(--ctmuted)}.ct-btn,.ct-back,.ct-mini{color:#fff;border:1px solid var(--ctline);border-radius:11px;background:rgba(255,255,255,.04);cursor:pointer}.ct-btn,.ct-back{padding:10px 13px;text-decoration:none}.ct-btn.primary{background:linear-gradient(135deg,#7359e8,#3f8cff);border-color:transparent}.ct-hero,.ct-stage,.ct-side,.ct-card,.ct-settings,.ct-log{border:1px solid var(--ctline);border-radius:18px;background:var(--ctpanel);box-shadow:0 15px 50px rgba(0,0,0,.16)}.ct-hero{padding:20px;margin-bottom:16px}.ct-hero h2{margin:0 0 7px;font-size:23px}.ct-hero p{margin:0;color:var(--ctmuted);line-height:1.5}.ct-status{display:inline-flex;margin-top:11px;padding:6px 9px;border-radius:999px;background:rgba(87,226,173,.08);color:var(--ctgood);font-size:11px}.ct-workspace{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(300px,.75fr);gap:16px}.ct-stage,.ct-side{padding:15px}.ct-stage-head,.ct-side-head,.ct-log-head{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:11px}.ct-stage-head h3,.ct-side-head h3{margin:0;font-size:15px}.ct-stage-head small,.ct-side-head small{color:var(--ctmuted)}.ct-screen{position:relative;aspect-ratio:16/9;border-radius:14px;overflow:hidden;background:radial-gradient(circle at 50% 40%,#1c2440,#090c15 70%);border:1px solid var(--ctline);display:grid;place-items:center}.ct-screen video{width:100%;height:100%;object-fit:contain;display:none}.ct-screen.demo video{display:block}.ct-screen.blurred video{filter:blur(var(--blur,18px))}.ct-placeholder{text-align:center;color:var(--ctmuted);padding:20px}.ct-placeholder b{display:block;color:#fff;font-size:17px;margin-bottom:5px}.ct-screen.demo .ct-placeholder{display:none}.ct-live-badge{position:absolute;left:10px;top:10px;z-index:2;padding:5px 8px;border-radius:999px;background:rgba(255,50,80,.9);font-size:10px;display:none}.ct-screen.demo .ct-live-badge{display:block}.ct-chat-overlay{position:absolute;right:10px;bottom:10px;width:min(46%,290px);display:none;gap:5px;flex-direction:column;align-items:flex-end;z-index:3}.ct-screen.chat-on .ct-chat-overlay{display:flex}.ct-msg{background:rgba(5,8,16,.78);backdrop-filter:blur(9px);border:1px solid rgba(255,255,255,.1);padding:6px 8px;border-radius:9px;font-size:10px;max-width:100%;opacity:var(--overlay,.92)}.ct-donate{position:absolute;left:10px;bottom:10px;z-index:3;padding:8px 10px;border-radius:11px;background:linear-gradient(135deg,#f0a84b,#ef4f7a);font-size:11px;display:none}.ct-screen.alert .ct-donate{display:block}.ct-controls,.ct-actions{display:flex;flex-wrap:wrap;gap:7px;margin-top:10px}.ct-mini{padding:7px 9px;font-size:11px}.ct-mini.on{border-color:rgba(87,226,173,.5);color:var(--ctgood)}.ct-side textarea,.ct-setting input,.ct-setting select{width:100%;box-sizing:border-box;border:1px solid var(--ctline);background:#0b0f1b;color:#fff;border-radius:10px;padding:9px;outline:none}.ct-side textarea{min-height:90px;resize:vertical}.ct-result{margin-top:9px;padding:10px;border:1px solid var(--ctline);border-radius:10px;color:#dbe2f0;white-space:pre-wrap;font-size:12px;line-height:1.45;min-height:42px}.ct-tools{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:16px}.ct-card{padding:15px;min-height:165px;display:flex;flex-direction:column}.ct-icon{width:38px;height:38px;border-radius:11px;display:grid;place-items:center;background:rgba(124,92,255,.1);font-size:18px;margin-bottom:10px}.ct-card h3{margin:0 0 4px;font-size:14px}.ct-card p{margin:0;color:var(--ctmuted);font-size:11px;line-height:1.45;flex:1}.ct-settings{margin-top:16px;padding:15px}.ct-settings h3{margin:0 0 10px;font-size:15px}.ct-setting-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}.ct-setting label{display:block;color:var(--ctmuted);font-size:10px;margin-bottom:4px}.ct-setting input,.ct-setting select{font-size:11px}.ct-setting.check{display:flex;align-items:center;gap:7px;padding-top:17px}.ct-setting.check label{margin:0}.ct-setting.check input{width:auto}.ct-log{margin-top:16px;padding:12px;background:#080b13}.ct-log-head{color:var(--ctmuted);font-size:10px}.ct-log-body{max-height:170px;overflow:auto;font:10px/1.5 ui-monospace,monospace;color:#b9c3d8}.ct-log-body div{padding:2px 0}.good{color:var(--ctgood)}.ct-note{margin-top:13px;padding:12px 14px;border:1px dashed rgba(124,92,255,.32);border-radius:13px;color:var(--ctmuted);font-size:10px;line-height:1.5}
