<body class="dashboard-page">
<div class="dashboard-ambient ambient-a"></div><div class="dashboard-ambient ambient-b"></div>
<main class="ct">
<header class="ct-head"><div class="ct-brand"><div class="ct-orb">✦</div><div><h1>Creator Tools</h1><p>Evruni AI tools for streamers</p></div></div><a class="ct-back" href="/">← Evruni</a></header>
<section class="ct-hero"><div class="eyebrow">EVRUNI CREATOR</div><h2>Стрим-пульт без постоянной нагрузки на сервер</h2><p>Экран, микрофон, blur, overlay и тестовые алерты работают локально в браузере. Сервер получает запрос только когда ты нажимаешь AI-инструмент или отмечаешь событие.</p><span class="ct-status">● Lightweight / event-driven</span></section>
<section class="ct-workspace">
<div class="ct-stage"><div class="ct-stage-head"><div><h3>🖥️ Демонстрация экрана</h3><small>Экран не отправляется на Evruni</small></div><button class="ct-btn primary" id="shareBtn">Начать</button></div>
<div class="ct-screen" id="screen"><span class="ct-live-badge">● LIVE PREVIEW</span><video id="screenVideo" autoplay muted playsinline></video><div class="ct-placeholder"><b>Предпросмотр стрима</b>Выбери окно, вкладку или весь экран.</div><div class="ct-chat-overlay"><div class="ct-msg">👤 Привет, Evruni!</div><div class="ct-msg">🔥 Крутой момент!</div><div class="ct-msg">💬 Когда следующий стрим?</div></div><div class="ct-donate" id="donateBadge">💰 Донат +500 ₽ · Спасибо!</div></div>
<div class="ct-controls"><button class="ct-mini" id="blurBtn">🔞 Censor</button><button class="ct-mini" id="overlayBtn">🎨 Overlay</button><button class="ct-mini" id="alertBtn">🔔 Тест доната</button><button class="ct-mini" id="stopBtn">⏹ Стоп</button></div></div>
<aside class="ct-side"><div class="ct-side-head"><div><h3>⚡ Event Console</h3><small>Одна команда = один запрос</small></div><span class="good">● ready</span></div>
<textarea id="eventText" placeholder="Сообщение зрителя, момент стрима или событие…"></textarea>
<div class="ct-actions"><button class="ct-mini" data-ai="chatbot">💬 Ответить</button><button class="ct-mini" data-ai="moderate">🛡️ Модерация</button><button class="ct-mini" data-ai="copilot">🧠 Copilot</button></div>
<div class="ct-result" id="aiResult">Результат появится здесь.</div>
<div class="ct-actions"><button class="ct-mini" id="clipBtn">✂️ Клип</button><button class="ct-mini" id="translateBtn">🌍 Перевести</button><button class="ct-mini" id="shortsBtn">📱 Shorts</button><button class="ct-mini" id="summaryBtn">📝 Summary</button></div></aside>
</section>
<section class="ct-tools" id="tools"></section>
<section class="ct-settings"><h3>⚙️ Настройки Creator Tools</h3><div class="ct-setting-grid">
<div class="ct-setting"><label>Язык ответов AI</label><select id="language"><option value="ru">Русский</option><option value="en">English</option><option value="de">Deutsch</option><option value="es">Español</option></select></div>
<div class="ct-setting"><label>Язык перевода</label><select id="targetLanguage"><option value="English">English</option><option value="Russian">Russian</option><option value="German">German</option><option value="Spanish">Spanish</option><option value="French">French</option></select></div>
<div class="ct-setting"><label>Сила Blur: <span id="blurValue">18</span>px</label><input id="blurRange" type="range" min="0" max="32" value="18"></div>
<div class="ct-setting"><label>Прозрачность Overlay: <span id="overlayValue">92</span>%</label><input id="overlayRange" type="range" min="30" max="100" value="92"></div>
<div class="ct-setting"><label>Текст тестового доната</label><input id="alertText" value="💰 Донат +500 ₽ · Спасибо!"></div>
<div class="ct-setting"><label>Длительность алерта, сек.</label><input id="alertDuration" type="number" min="1" max="15" value="4"></div>
<div class="ct-setting check"><input id="aiEnabled" type="checkbox" checked><label>Разрешить AI-запросы</label></div>
<div class="ct-setting check"><input id="localMode" type="checkbox" checked><label>Local-first режим</label></div>
</div><div class="ct-actions"><button class="ct-mini" id="saveSettings">💾 Сохранить настройки</button><button class="ct-mini" id="resetSettings">↺ Сбросить</button></div></section>
<div class="ct-log"><div class="ct-log-head"><span>Event log</span><span id="eventCount">0 событий</span></div><div class="ct-log-body" id="log"></div></div>
<div class="ct-note"><b>Нагрузка:</b> нет polling, постоянного WebSocket, фонового AI или загрузки видео на сервер. AI вызывается только действием пользователя/событием и ограничен серверным rate limit. Реальные Twitch/YouTube/Kick донаты и подписки требуют OAuth/webhook-подключения; здесь тестовый алерт уже работает локально.</div>
</main>
<script>
(()=>{
const API='/api/creator_tools.php',CSRF=document.querySelector('meta[name="csrf-token"]')?.content||'',KEY='evruni_creator_settings_v2',defaults={language:'ru',targetLanguage:'English',blur:18,overlay:92,alertText:'💰 Донат +500 ₽ · Спасибо!',alertDuration:4,aiEnabled:true,localMode:true};
const $=s=>document.querySelector(s),logEl=$('#log');let events=0,screenStream=null,micStream=null,audioCtx=null;
const tools=[['🎙️','Voice Cleaner','Локальное шумоподавление, echo cancellation и auto gain.','mic'],['💬','AI Chat Bot','Короткий ответ зрителю по событию.','chat'],['🛡️','AI Moderator','Проверка нового сообщения без постоянного сканирования.','moderation'],['🎨','Chat Overlay','Чат поверх предпросмотра с локальными настройками.','overlay'],['🔔','Smart Alerts','Тест доната/рейда/подписки без внешнего webhook.','alerts'],['🌍','Live Translator','Перевод выбранной реплики только по запросу.','translator'],['🔞','Content Censor','Мгновенный blur предпросмотра.','censor'],['✂️','Auto Clips','Отметка момента; тяжёлая нарезка не запускается в фоне.','clips'],['🧠','Stream Copilot','Одна полезная подсказка на одно событие.','copilot'],['📊','Stream Analytics','Локальный счётчик событий текущей сессии.','analytics'],['📝','Stream Summary','Сводка по накопленным событиям одним запросом.','summary'],['📱','Shorts Maker','HOOK + TITLE + CAPTION + HASHTAGS для момента.','shorts']];
let settings=loadSettings();
function loadSettings(){try{return {...defaults,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch(e){return {...defaults}}}
function saveSettings(){localStorage.setItem(KEY,JSON.stringify(settings));log('Настройки сохранены локально');applySettings()}
function applySettings(){$('#language').value=settings.language;$('#targetLanguage').value=settings.targetLanguage;$('#blurRange').value=settings.blur;$('#overlayRange').value=settings.overlay;$('#blurValue').textContent=settings.blur;$('#overlayValue').textContent=settings.overlay;$('#alertText').value=settings.alertText;$('#alertDuration').value=settings.alertDuration;$('#aiEnabled').checked=!!settings.aiEnabled;$('#localMode').checked=!!settings.localMode;document.documentElement.style.setProperty('--blur',settings.blur+'px');document.documentElement.style.setProperty('--overlay',(settings.overlay/100).toFixed(2));$('#donateBadge').textContent=settings.alertText}
function readSettings(){settings={...settings,language:$('#language').value,targetLanguage:$('#targetLanguage').value,blur:+$('#blurRange').value,overlay:+$('#overlayRange').value,alertText:$('#alertText').value.slice(0,160),alertDuration:Math.max(1,Math.min(15,+$('#alertDuration').value||4)),aiEnabled:$('#aiEnabled').checked,localMode:$('#localMode').checked};applySettings()}
function log(s){events++;$('#eventCount').textContent=events+' событий';const d=document.createElement('div');d.textContent=new Date().toLocaleTimeString()+' · '+s;logEl.prepend(d);if(logEl.children.length>80)logEl.lastElementChild.remove()}
function render(){$('#tools').innerHTML=tools.map(t=>`<article class="ct-card"><div class="ct-icon">${t[0]}</div><h3>${t[1]}</h3><p>${t[2]}</p><div class="ct-actions"><button class="ct-mini tool-action" data-action="${t[3]}">Запустить</button></div></article>`).join('')}
async function ai(action,text){if(!settings.aiEnabled){$('#aiResult').textContent='AI отключён в настройках.';return}text=(text||'').trim();if(!text){$('#aiResult').textContent='Сначала введи событие или сообщение.';return}$('#aiResult').textContent='AI обрабатывает событие…';log('AI → '+action);try{const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify({action,text,language:settings.language,target_language:settings.targetLanguage})});const j=await r.json();if(!r.ok)throw new Error(j.error||'Ошибка');$('#aiResult').textContent=j.result||j.message||'Готово';log('AI ← '+action+' готово')}catch(e){$('#aiResult').textContent=e.message||'Creator Tool unavailable';log('Ошибка → '+action)}}
async function share(){if(screenStream){screenStream.getTracks().forEach(t=>t.stop());screenStream=null;$('#screen').classList.remove('demo');$('#screenVideo').srcObject=null;$('#shareBtn').textContent='Начать';log('Экран остановлен');return}try{screenStream=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false});$('#screenVideo').srcObject=screenStream;$('#screen').classList.add('demo');$('#shareBtn').textContent='Остановить';log('Экран запущен локально');screenStream.getVideoTracks()[0].addEventListener('ended',()=>share())}catch(e){log('Демонстрация отменена')}}
async function mic(){if(micStream){micStream.getTracks().forEach(t=>t.stop());micStream=null;if(audioCtx){audioCtx.close();audioCtx=null}log('Voice Cleaner остановлен');return}try{micStream=await navigator.mediaDevices.getUserMedia({audio:{noiseSuppression:true,echoCancellation:true,autoGainControl:true}});audioCtx=new AudioContext();const src=audioCtx.createMediaStreamSource(micStream),comp=audioCtx.createDynamicsCompressor();comp.threshold.value=-38;comp.knee.value=18;comp.ratio.value=4;comp.attack.value=.003;comp.release.value=.15;src.connect(comp);log('Voice Cleaner: микрофон обрабатывается локально')}catch(e){log('Нет доступа к микрофону')}}
function alertTest(){const s=$('#screen');s.classList.add('alert');log('Тестовый алерт: '+settings.alertText);setTimeout(()=>s.classList.remove('alert'),settings.alertDuration*1000)}
function clip(){log('Auto Clips: момент отмечен');fetch(API,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify({action:'clip_note'})}).catch(()=>{})}
function summaryText(){const lines=[...logEl.querySelectorAll('div')].slice(0,30).map(x=>x.textContent).join('\n');return lines||$('#eventText').value}
$('#shareBtn').onclick=share;$('#stopBtn').onclick=()=>{if(screenStream)share()};$('#blurBtn').onclick=()=>{$('#screen').classList.toggle('blurred');log('Censor: '+($('#screen').classList.contains('blurred')?'ON':'OFF'))};$('#overlayBtn').onclick=()=>{$('#screen').classList.toggle('chat-on');log('Overlay: '+($('#screen').classList.contains('chat-on')?'ON':'OFF'))};$('#alertBtn').onclick=alertTest;$('#clipBtn').onclick=clip;$('#translateBtn').onclick=()=>ai('translate',$('#eventText').value);$('#shortsBtn').onclick=()=>ai('shorts',$('#eventText').value);$('#summaryBtn').onclick=()=>ai('summary',summaryText());
document.querySelectorAll('[data-ai]').forEach(b=>b.onclick=()=>ai(b.dataset.ai,$('#eventText').value));
document.addEventListener('click',e=>{const b=e.target.closest('.tool-action');if(!b)return;const a=b.dataset.action;if(a==='mic')mic();else if(a==='overlay')$('#overlayBtn').click();else if(a==='alerts')alertTest();else if(a==='censor')$('#blurBtn').click();else if(a==='clips')clip();else if(a==='chat')ai('chatbot',$('#eventText').value);else if(a==='moderation')ai('moderate',$('#eventText').value);else if(a==='translator')$('#translateBtn').click();else if(a==='copilot')ai('copilot',$('#eventText').value);else if(a==='shorts')$('#shortsBtn').click();else if(a==='summary')$('#summaryBtn').click();else if(a==='analytics')log('Analytics: '+events+' событий в текущей сессии')});
$('#blurRange').oninput=()=>{settings.blur=+$('#blurRange').value;$('#blurValue').textContent=settings.blur;applySettings()};$('#overlayRange').oninput=()=>{settings.overlay=+$('#overlayRange').value;$('#overlayValue').textContent=settings.overlay;applySettings()};$('#saveSettings').onclick=()=>{readSettings();saveSettings()};$('#resetSettings').onclick=()=>{settings={...defaults};saveSettings()};['language','targetLanguage','alertText','alertDuration','aiEnabled','localMode'].forEach(id=>$('#'+id).addEventListener('change',readSettings));
render();applySettings();log('Creator Tools готов · local-first');
})();
</script>
</body>
</html>
